def better_method(rows):
    by_section = {}
    for section, method, passed, enrolled in rows:
        p, n = by_section.setdefault(section, {}).get(method, (0, 0))
        by_section[section][method] = (p + passed, n + enrolled)
    wins = set()
    for counts in by_section.values():
        if "A" not in counts or "B" not in counts:
            continue
        ra = counts["A"][0] / counts["A"][1]
        rb = counts["B"][0] / counts["B"][1]
        wins.add("A" if ra > rb else "B" if rb > ra else "tie")
    if wins == {"A"}:
        return "A"
    if wins == {"B"}:
        return "B"
    return "tie"
```

